  let entities=new Map(model.entities.map(e=>[e.id,e])),definition=model.surfaceDefinition,boundary=entities.get(definition.boundary),holes=definition.holes.map(id=>entities.get(id)),breaklines=definition.breaklines.map(id=>entities.get(id));
