function exportDialog(){showModal('Export your work','<div class="export-options"><button id="exportDXFButton"><b>AutoCAD ASCII DXF ↗</b><small>Drawing geometry, layers, survey elevations and TIN 3D faces. Civil objects export as basic CAD geometry.</small></button><button id="exportProjectButton"><b>Portable project ↗</b><small>Editable .draft file including layers, parcels, survey data, terrain and embedded image.</small></button><button id="exportSheetButton"><b>Site plan sheet ↗</b><small>Choose a preloaded border, paper size, scale and project details. Preview and export a vector SVG sheet.</small></button><button id="exportSurveyButton"><b>Survey point CSV ↗</b><small>Point, northing, easting, elevation, description.</small></button></div>');$('exportDXFButton').onclick=safely(()=>{download(exportDXF(model),filename('dxf'),'application/dxf');toast('ASCII DXF exported')});$('exportProjectButton').onclick=()=>saveProject(true);$('exportSurveyButton').onclick=safely(exportPoints);$('exportSheetButton').onclick=safely(()=>sheetEditor())}

function roadmap(){showModal('Civil development roadmap',`<p>This is a working civil design foundation, not a Civil 3D equivalent. Features marked “available” are implemented with the limits below. Future rows are a development backlog, not scheduled or running work.</p><table><thead><tr><th>AREA</th><th>STATUS</th><th>CURRENT SCOPE / NEXT WORK</th></tr></thead><tbody>${[
['2D drafting','Available','Lines, polylines, rectangles, circles, CCW arcs, text and dimensions. Grid, endpoint, midpoint, center and quadrant snaps.'],
['Editing & layers','Available','Move, copy, rotate, scale, reverse, line trim, line/circle offsets and convex polygon insets. Layer color, linetype, lineweight, visibility and locking; selected objects can be reassigned to layers.'],
['Symbols & annotations','Available','Catalog civil symbols stamp as grouped editable geometry. Model-space leaders and generated major-contour labels are editable; annotations export through DXF and sheet SVG/PDF.'],
['Parcels & survey','Available','Bearing/distance traverse, closure gap, closed parcels, acreage and course reports. CSV survey-point imports.'],
['Terrain','Available','Unconstrained TIN plus selected-linework constrained surfaces: largest closed ring as boundary, other closed rings as holes, open lines/polylines as breaklines. Boundary elevations are interpolated; breakline vertices must match survey points. 1,500-vertex limit.'],
['Alignments & profiles','Available','Tangent-only alignments, station labels, current-TIN sampling and existing-ground profile chart/CSV.'],
['File exchange & sheets','Available','Versioned Draft JSON, ASCII DXF exchange with bounded bulge/classic-polyline tessellation and supported single-loop hatches, survey CSV, image underlay and starter plans. Editable multi-sheet Paper Space supports custom borders, vectors, bounded images, tables, independently framed model viewports, zoom/pan and SVG/PDF output.'],
['Drafting expansion','Future','User-defined reusable blocks, fillet/chamfer, advanced trim/extend, richer object snaps, constraints, label styles and native sheet sets.'],
['Terrain & survey expansion','Future','Independent validation datasets, larger datasets, geodetic coordinate systems and survey adjustment.'],
['Roadway geometry','Future','Circular curves, spirals, vertical design profiles, superelevation and design-criteria checking.'],
['Corridors & grading','Future','Assemblies, subassemblies, corridors, intersections, feature-line grading, daylighting, sections and surface-to-surface quantities.'],
['Drainage & utilities','Future','Gravity/pressure pipe networks, structures, hydraulic and hydrologic calculations and network profiles.'],
['Production & interoperability','Future','Native DWG/Civil 3D custom-object interoperability, LandXML, references, native sheet sets, collaboration and comprehensive engineering validation.']
].map(([area,status,desc])=>`<tr><td>${esc(area)}</td><td><span class="status-tag ${status==='Future'?'future':''}">${status}</span></td><td>${esc(desc)}</td></tr>`).join('')}</tbody></table><p class="note">Use for concept development and geometry exploration. This release has no engineering certification, automated design-code validation or native Civil 3D object compatibility.</p>`)}
