  let value={...defaultSheet(),...clone(model.sheet||{}),...overrides};
  for(let key of Object.keys(value)){let element=$('s_'+key);if(!element)continue;value[key]=element.type==='checkbox'?element.checked:element.type==='number'?Number(element.value):element.value}
