let lineOperationBoundaryIds=null,cornerCommand=null;
function beginLineworkOperation(kind){
 if(view3d)throw Error('Switch to plan view before trimming or extending LINEs.');
 let boundaries=ensureSelection();
 if(boundaries.some(entity=>entity.type!=='line'))throw Error('Select only boundary LINE entities before starting trim or extend.');
 if(boundaries.some(entity=>!visible(entity)))throw Error('Boundary LINEs must be on visible layers.');
 let ids=boundaries.map(entity=>entity.id);
 setTool(kind==='trim'?'trimTargets':'extendTargets');
 lineOperationBoundaryIds=ids;
 toast(kind==='trim'?'Click a LINE segment to trim; select another segment or press Enter to finish.':'Click near a LINE endpoint to extend; select another endpoint or press Enter to finish.');
}
function beginCornerOperation(kind){
 if(view3d)throw Error('Switch to plan view before filleting or chamfering LINEs.');
 let entities=ensureSelection();
 if(entities.length!==2||entities.some(entity=>entity.type!=='line'||entity.symbolGroup))throw Error(`Select exactly two ungrouped, intersecting LINEs before starting ${kind}.`);
 setTool(kind==='fillet'?'filletCorner':'chamferCorner');
 cornerCommand={kind,ids:entities.map(entity=>entity.id)};
 $('instruction').textContent=`Click the desired corner formed by the two selected LINEs.`;
}
function finishLineworkOperation(){
 if(!['trimTargets','extendTargets'].includes(tool))return;
 lineOperationBoundaryIds=null;setTool('select');toast('Linework command finished.');
}
function activeBoundaryLines(){
 let ids=lineOperationBoundaryIds||[],boundaries=ids.map(id=>model.entities.find(entity=>entity.id===id));
 if(!boundaries.length||boundaries.some(entity=>!entity||entity.type!=='line'))throw Error('Boundary selection changed. Select boundary LINEs and restart the command.');
 if(boundaries.some(entity=>layer(entity).locked))throw Error('Unlock boundary LINE layers before editing.');
 return boundaries;
}
function nearestDraftLine(point,excluded){
 let result=null,best=10/scale;
 for(let entity of model.entities){
  if(entity.type!=='line'||!visible(entity)||excluded.has(entity.id))continue;
  let closest=G.closest(point,entity.a,entity.b),d=G.distance(point,closest);
  if(d<best){best=d;result=entity}
 }
 return result;
}
function applyTrimClick(point){
 let boundaryIds=new Set(lineOperationBoundaryIds||[]),target=nearestDraftLine(point,boundaryIds);
 if(!target)throw Error('Click a visible target LINE away from the selected boundary LINEs.');
 if(target.symbolGroup)throw Error('Grouped symbol LINEs are protected. Ungroup or edit the symbol definition first.');
 if(layer(target).locked)throw Error('Unlock the target LINE layer before trimming.');
 let boundaries=activeBoundaryLines(),result=G.trimLineByBoundaries(target,boundaries,point);
 let created=[];
 mutate(()=>{
  let index=model.entities.findIndex(entity=>entity.id===target.id);
  if(index<0)throw Error('The target LINE no longer exists.');
  if(!result.segments.length){model.entities.splice(index,1);return}
  target.a={...target.a,...result.segments[0].a};target.b={...target.b,...result.segments[0].b};
  if(result.segments.length>1){
   let split={...clone(target),id:uid(),a:{...target.a,...result.segments[1].a},b:{...target.b,...result.segments[1].b}};
   model.entities.splice(index+1,0,split);created.push(split.id);
  }
 });
 setSelection([...boundaryIds,target.id,...created].filter(id=>model.entities.some(entity=>entity.id===id)));
 toast(created.length?'Trimmed target LINE and split it into two segments.':'Trimmed target LINE.');
}
function applyExtendClick(point){
 let boundaryIds=new Set(lineOperationBoundaryIds||[]),target=nearestDraftLine(point,boundaryIds);
 if(!target)throw Error('Click near the endpoint of a visible target LINE.');
 if(target.symbolGroup)throw Error('Grouped symbol LINEs are protected. Ungroup or edit the symbol definition first.');
 if(layer(target).locked)throw Error('Unlock the target LINE layer before extending.');
 let da=G.distance(point,target.a),db=G.distance(point,target.b);
 if(Math.min(da,db)>15/scale||Math.abs(da-db)<1/scale)throw Error('Click clearly near the endpoint you want to extend.');
 let endpoint=da<db?'a':'b',changed=G.extendLineToBoundaries(target,activeBoundaryLines(),endpoint);
 mutate(()=>{let current=model.entities.find(entity=>entity.id===target.id);if(!current)throw Error('The target LINE no longer exists.');current[endpoint]=changed[endpoint]});
 setSelection([...boundaryIds,target.id]);toast('Extended target LINE to its nearest boundary.');
}
function applyCornerClick(point){
 let command=cornerCommand;if(!command)throw Error('Select two LINEs and restart the corner command.');
 let [first,second]=command.ids.map(id=>model.entities.find(entity=>entity.id===id));
 if(!first||!second||first.type!=='line'||second.type!=='line')throw Error('The selected LINEs changed. Select them again.');
 if(layer(first).locked||layer(second).locked)throw Error('Unlock both selected LINE layers before editing.');
 cornerCommand=null;setTool('select');
 let field=command.kind==='fillet'?{id:'radius',label:`Fillet radius (${model.units})`,value:5}:{id:'distance',label:`Chamfer distance along each LINE (${model.units})`,value:5};
 formDialog(command.kind==='fillet'?'Fillet selected LINEs':'Chamfer selected LINEs',[field],values=>{
  let result=command.kind==='fillet'?G.filletLines(first,second,values.radius,point):G.chamferLines(first,second,values.distance,point);
  let addition={...result[command.kind==='fillet'?'arc':'connector'],id:uid(),layer:first.layer};
  mutate(()=>{
   let firstIndex=model.entities.findIndex(entity=>entity.id===first.id),secondIndex=model.entities.findIndex(entity=>entity.id===second.id);
   if(firstIndex<0||secondIndex<0)throw Error('A selected LINE no longer exists.');
   model.entities[firstIndex]=result.first;model.entities[secondIndex]=result.second;
   model.entities.push(addition);
  });
  setSelection([first.id,second.id,addition.id]);toast(command.kind==='fillet'?'Fillet created; both LINEs were trimmed to tangent points.':'Chamfer created; both LINEs were trimmed to the chamfer endpoints.');
 },command.kind==='fillet'?'The chosen radius must fit both LINEs. The tangent arc and shortened LINEs are created together.':'The distance is measured from the intersection along each selected LINE.');
}
const originalSetTool=setTool;
setTool=function(next){
 if(['trimTargets','extendTargets'].includes(tool)&&!['trimTargets','extendTargets'].includes(next))lineOperationBoundaryIds=null;
 if(['filletCorner','chamferCorner'].includes(tool)&&!['filletCorner','chamferCorner'].includes(next))cornerCommand=null;
 originalSetTool(next);
 if(next==='trimTargets')$('instruction').textContent='Click a LINE segment to remove between selected boundary LINEs. Press Enter or Esc to finish.';
 if(next==='extendTargets')$('instruction').textContent='Click near the endpoint to extend to the nearest selected boundary LINE. Press Enter or Esc to finish.';
 if(next==='filletCorner')$('instruction').textContent='Click the corner formed by the two selected LINEs; then enter a fillet radius.';
 if(next==='chamferCorner')$('instruction').textContent='Click the corner formed by the two selected LINEs; then enter a chamfer distance.';
};
bind('trimLines',()=>beginLineworkOperation('trim'));
bind('extendLines',()=>beginLineworkOperation('extend'));
bind('filletLines',()=>beginCornerOperation('fillet'));
bind('chamferLines',()=>beginCornerOperation('chamfer'));
const originalCanvasPointerDown=canvas.onpointerdown;
canvas.onpointerdown=safely(event=>{
 if(['trimTargets','extendTargets','filletCorner','chamferCorner'].includes(tool)){
  if(event.button===2)return;
  if(event.button!==0||spaceDown)return originalCanvasPointerDown(event);
  event.preventDefault();let point=rawWorld(event);
  if(tool==='trimTargets')applyTrimClick(point);
  else if(tool==='extendTargets')applyExtendClick(point);
  else applyCornerClick(point);
  return;
 }
 return originalCanvasPointerDown(event);
});
document.addEventListener('keydown',event=>{
 if($('modal').open||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName)||event.key!=='Enter')return;
 if(['trimTargets','extendTargets'].includes(tool)){event.preventDefault();finishLineworkOperation()}
});
const acceptPointWithTextStyles=acceptPoint;
acceptPoint=function(point,forceOrtho=shiftConstraint){
 if(tool!=='text')return acceptPointWithTextStyles(point,forceOrtho);
 let text=$('annotation').value.trim(),style=textStyleFor(model),height=num('height');
 if(!text)throw Error('Enter annotation text first.');
 if(height<0||height>100)throw Error('Text height must be no more than 100 '+model.units+'.');
 addEntity({type:'text',a:point,text,textStyleId:style.id,...(height>0?{size:height}:{})});
};
const editPropertiesWithTextStyles=editProperties;
editProperties=function(){
 let entity=editable();
 if(entity.type!=='text'||entity.contourLabel)return editPropertiesWithTextStyles();
 showModal('Edit text annotation',`<form id="styledTextEditForm"><label>Object name<input id="styledTextName"></label><label>Layer<select id="styledTextLayer">${model.layers.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('')}</select></label><div class="row"><label>Easting<input id="styledTextX" type="number" step="any"></label><label>Northing<input id="styledTextY" type="number" step="any"></label></div><label>Text<input id="styledTextValue" maxlength="500"></label><label>Named text style<select id="styledTextStyle">${model.textStyles.map(style=>`<option value="${esc(style.id)}">${esc(style.name)}</option>`).join('')}</select></label><label>Text height (${esc(model.units)})<input id="styledTextHeight" type="number" min=".1" max="100" step="any"></label><div class="form-error" id="styledTextError"></div><button class="primary">Save text</button></form>`);
 $('styledTextName').value=entity.name||'';$('styledTextLayer').value=entity.layer;$('styledTextX').value=entity.a.x;$('styledTextY').value=entity.a.y;$('styledTextValue').value=entity.text;$('styledTextStyle').value=entity.textStyleId||model.activeTextStyleId;$('styledTextHeight').value=entity.size??textStyleFor(model,entity.textStyleId).textHeight;
 $('styledTextStyle').onchange=()=>{let style=textStyleFor(model,$('styledTextStyle').value);if(entity.size===undefined)$('styledTextHeight').value=style.textHeight};
 $('styledTextEditForm').onsubmit=event=>{event.preventDefault();try{
  let layerTarget=model.layers.find(item=>item.id===$('styledTextLayer').value),style=textStyleFor(model,$('styledTextStyle').value),x=Number($('styledTextX').value),y=Number($('styledTextY').value),height=Number($('styledTextHeight').value),text=$('styledTextValue').value;
  if(!layerTarget||layerTarget.locked)throw Error('Choose a visible, unlocked text layer.');
  if(![x,y,height].every(Number.isFinite)||height<.1||height>100||!text.trim()||text.length>500)throw Error('Enter finite coordinates, text, and a height from 0.1 to 100.');
  mutate(()=>{entity.name=$('styledTextName').value;entity.layer=layerTarget.id;entity.a={x,y};entity.text=text;entity.textStyleId=style.id;if(Math.abs(height-style.textHeight)<1e-8)delete entity.size;else entity.size=height});
  $('modal').close();
 }catch(error){$('styledTextError').textContent=error.message}}
};
